{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "These signs include evidence of safety, health, or behavior concerns, such as bullying, threats of violence, substance abuse, mental health issues, self-harm, or suicidal thoughts.",
      "rationale": "Conveys the broad definition and several examples, but omits harassment, intimidation, and cyberbullying and does not expressly cover both engaging in and experiencing misconduct or making and receiving threats."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill would require Tennessee local education agencies (LEAs) and public charter schools to use a computer-based system to record students’ early warning signs. These signs include evidence of safety, health, or behavior concerns, such as bullying, threats of violence, substance abuse, mental health issues, self-harm, or suicidal thoughts. Teachers and school staff would have to enter the information, and LEAs and charter schools would have to train them to recognize signs and use the system.",
      "rationale": "Conveys the schools' system obligation and mandatory teacher and staff entry of student warning signs. The summary separately states the existing-system exemption."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Teachers and school staff would have to enter the information, and LEAs and charter schools would have to train them to recognize signs and use the system.",
      "rationale": "Covers training teachers and staff in identifying signs and using the system, with the exemption explained later."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The system would have to align with specified bullying, discipline, and school safety policies.",
      "rationale": "Conveys alignment in all three subject areas, but substitutes generic policies for the School Discipline Act and each adopted school safety plan and does not convey the full scope of the harassment-related policy."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "It would have to store the entries",
      "rationale": "In context, storing the required teacher and staff entries conveys the database's receiving and maintaining function without needing the technical term."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "It would have to store the entries and immediately notify the LEA’s threat assessment team personnel or a designated charter school employee.",
      "rationale": "Conveys immediate entry-triggered notification and the correct recipients."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The person notified would review the entry and any earlier entries for that student and decide whether further action is needed.",
      "rationale": "Conveys review of the current and previous notifications and the decision on further action. The following sentence supplies the exemption."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Each LEA and charter school would have to report annually to the education department on the preceding school year. The report would include counts of warning signs",
      "rationale": "Identifies the reporting entities, recipient, annual frequency, preceding-school-year period, and warning-sign count."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "breakdowns by the teachers or staff who entered them",
      "rationale": "Conveys breakdowns by entry source, but omits teacher grade levels and subject areas and staff position, assignment, and duties."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "counts for students with multiple entries",
      "rationale": "Recognizes reporting on students with multiple entries, but does not clearly require both the number of such students and the number of signs for each student."
    },
    {
      "proposition_id": "P11",
      "status": "partial",
      "summary_quote": "general descriptions of the signs and responses. Reports could not identify students",
      "rationale": "Conveys general descriptions and the identification prohibition, but does not specify that the school's response to each entered sign must be described."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "Reports could not identify students",
      "rationale": "Conveys the prohibition on identifying information throughout the annual reports."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "Reports could not identify students and would have to comply with applicable privacy laws.",
      "rationale": "Conveys the comprehensive privacy-law compliance requirement; the individual statutory names and citations are not essential to this description."
    },
    {
      "proposition_id": "P14",
      "status": "full",
      "summary_quote": "If an LEA or charter school did not comply, the education commissioner could withhold an amount of state funding the commissioner determines until it complies.",
      "rationale": "Conveys noncompliance as the condition, the commissioner's discretion over withholding and amount, and compliance as the endpoint."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "These system, training, and review requirements would not apply to an LEA or charter school that implemented a system for documenting early warning signs before July 1, 2026, if it continues to maintain and use that system.",
      "rationale": "States the exempted requirements, qualifying system, cutoff date, and continued maintenance and use condition. The subsequent reporting requirement expressly applies to each LEA and charter school."
    },
    {
      "proposition_id": "P16",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2026.",
      "rationale": "States the correct effective date."
    }
  ]
}
